    public static boolean isValidUrl(String url) {
        String pattern = "^(https?:\\/\\/)?([a-zA-Z0-9.-]+\\.[a-zA-Z]{2,}\\/[^\s]*)$";
        Pattern regex = Pattern.compile(pattern);
        Matcher match = regex.matcher(url);
        return match.matches();
    }
}
